:root {
  --bg: #1b1b2f;
  --card: #16213e;
  --accent: #e94560;
  --text: #f5f5f5;
  --muted: #a0a0b8;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background: var(--bg);
  background-image: linear-gradient(var(--bg) 1px, transparent 1px), linear-gradient(90deg, var(--bg) 1px, transparent 1px);
  background-size: 24px 24px;
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
  font-size: 18px;
  color: var(--text);
}
.card {
  width: 100%;
  max-width: 420px;
  padding: 32px 24px;
  background: var(--card);
  border: 4px solid var(--accent);
  box-shadow: 8px 8px 0 #000;
  text-align: center;
}
h1 {
  margin: 0 0 24px;
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
}
#count {
  display: block;
  margin: 0 0 28px;
  padding: 16px;
  font-size: 3rem;
  font-weight: 700;
  background: var(--bg);
  border: 4px solid var(--muted);
  color: var(--text);
  overflow-wrap: anywhere;
}
.controls {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: center;
}
button {
  flex: 1 1 90px;
  min-height: 52px;
  padding: 12px 16px;
  font-family: inherit;
  font-size: 1.05rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text);
  background: var(--bg);
  border: 3px solid var(--muted);
  box-shadow: 4px 4px 0 #000;
  cursor: pointer;
  transition: transform 0.05s, box-shadow 0.05s, background 0.15s;
}
button:hover { background: var(--accent); border-color: var(--text); }
button:focus-visible { outline: 3px solid var(--accent); outline-offset: 3px; }
button:active { transform: translate(4px, 4px); box-shadow: 0 0 0 #000; }
@media (max-width: 360px) {
  body { font-size: 16px; padding: 12px; }
  #count { font-size: 2.4rem; }
  button { flex: 1 1 100%; }
}

(function () {
  'use strict';
  var countEl = document.getElementById('count');
  var value = 0;

  function render() {
    countEl.textContent = String(value);
  }

  document.getElementById('increase').addEventListener('click', function () {
    value += 1;
    render();
  });

  document.getElementById('decrease').addEventListener('click', function () {
    value -= 1;
    render();
  });

  document.getElementById('reset').addEventListener('click', function () {
    value = 0;
    render();
  });

  render();
})();
